uniform float speed : 0.0 .. 2.0 = 0.4;
uniform float blob_size : 0.05 .. 0.3 = 0.15;
uniform float blob_count : 3.0 .. 12.0 = 7.0;
uniform float separation : 0.0 .. 1.0 = 0.3;
uniform vec3 color_a : color = 1.0, 0.3, 0.1;
uniform vec3 color_b : color = 1.0, 0.8, 0.2;
uniform vec3 bg_color : color = 0.1, 0.05, 0.02;

state fixed ph_y;
state fixed ph_r;
state fixed ph_rot;
state fixed k_y;
state fixed k_r;
state fixed sep;
state fixed bsize;
state fixed n_blobs;
state fixed3 col_a;
state fixed3 col_b;
state fixed3 col_bg;

void update() {
  ph_y = fract(ph_y + fixed(dt * speed * 0.6));
  ph_r = fract(ph_r + fixed(dt * speed * 0.35));
  ph_rot = fract(ph_rot + fixed(dt * speed * 0.15));
  k_y = fixed(2.0);
  k_r = fixed(4.0);
  sep = fixed(separation);
  bsize = fixed(blob_size);
  n_blobs = fixed(blob_count);
  col_a = fixed3(color_a);
  col_b = fixed3(color_b);
  col_bg = fixed3(bg_color);
}

fixed3 hsv2rgb_fixed(fixed h, fixed s, fixed v) {
  fixed i = floor(h * fixed(6.0));
  fixed f = h * fixed(6.0) - i;
  fixed p = v * (fixed(1.0) - s);
  fixed q = v * (fixed(1.0) - s * f);
  fixed t = v * (fixed(1.0) - s * (fixed(1.0) - f));
  fixed ii = mod(i, fixed(6.0));
  if (ii < fixed(1.0)) return fixed3(v, t, p);
  if (ii < fixed(2.0)) return fixed3(q, v, p);
  if (ii < fixed(3.0)) return fixed3(p, v, t);
  if (ii < fixed(4.0)) return fixed3(p, q, v);
  if (ii < fixed(5.0)) return fixed3(t, p, v);
  return fixed3(v, p, q);
}

vec3 shade(Led led) {
  fixed y = fixed(led.pos.y) / fixed(0.3);
  fixed r = fixed(led.pos.x) * fixed(led.pos.x) + fixed(led.pos.z) * fixed(led.pos.z);
  r = sqrt(r) / fixed(0.08);
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);

  fixed3 acc = fixed3(0.0, 0.0, 0.0);
  fixed total_w = fixed(0.0);

  for (int i = 0; i < 12; i = i + 1) {
    fixed fi = fixed(i);
    fixed fy = fract(fi * fixed(0.618) + ph_y);
    fixed fr = fract(fi * fixed(0.382) + ph_r);
    fixed fang = fract(fi * fixed(0.231) + ph_rot);

    fixed dy = abs(y - fy);
    if (dy > fixed(0.5)) dy = fixed(1.0) - dy;

    fixed dr = abs(r - fr);
    if (dr > fixed(0.5)) dr = fixed(1.0) - dr;

    fixed dang = abs(ang - fang);
    if (dang > fixed(0.5)) dang = fixed(1.0) - dang;

    fixed d2 = dy * dy * k_y + dr * dr * k_r + dang * dang * fixed(8.0);
    fixed w = exp(-d2 / (bsize * bsize * fixed(2.0)));

    fixed hi = fract(fi / n_blobs + ph_y * fixed(0.3));
    fixed3 col = mix(col_a, col_b, hi);

    acc = acc + col * w;
    total_w = total_w + w;
  }

  fixed3 result;
  if (total_w > fixed(0.0)) {
    result = acc / total_w;
  } else {
    result = col_bg;
  }

  return vec3(float(result.x), float(result.y), float(result.z));
}

